/**
 * Helper function to extract target_document based on tool type
 * @param toolDetails - The tool details object shape
 * @param toolType - The type of the tool
 * @returns The sys_id of the target document or empty string
 */
function extractTargetDocument(toolDetails: ObjectShape, toolType: string | undefined): string {
    if (!toolType) {
        return ''
    }

    // Map tool type to the corresponding field name
    const fieldMap: Record<string, string> = {
        capability: 'capabilityId',
        subflow: 'subflowId',
        action: 'flowActionId',
        catalog: 'catalogItemId',
        topic: 'virtualAgentId',
        topic_block: 'virtualAgentId',
    }

    const fieldName = fieldMap[toolType]
    if (!fieldName) {
        // For crud, script, and other types, check targetDocument
        return extractSysId(toolDetails.get('targetDocument')) || ''
    }

    // Extract the sys_id from the type-specific field
    const fieldValue = toolDetails.get(fieldName)
    return extractSysId(fieldValue) || ''
}

/**
 * Helper function to serialize a shape to JSON string
 * @param shape - The shape to serialize
 * @param toolType - The tool type (e.g., 'rag', 'crud') to determine how to serialize inputs
 * @param defaultValue - Default value to return if shape is undefined or empty
 * @returns JSON string representation of the shape
 */
function serializeToJson(shape: Shape | undefined, toolType: string | undefined, defaultValue = ''): string {
    if (!shape) {
        return defaultValue
    }

    if (shape.isArray()) {
        // For arrays, map each element's value and stringify the result
        return JSON.stringify(shape.getElements().map((element) => element.getValue()))
    } else if (shape.isObject()) {
        const objectValue = shape.getValue()

        // Check tool type to determine serialization strategy
        if (toolType === 'crud' && isToolInputType(objectValue)) {
            // Transform ToolInputType to complex inputs JSON
            const transformedInputs = generateToolInputs(objectValue)
            return JSON.stringify(transformedInputs)
        }

        if (toolType === 'search_retrieval') {
            // Transform RagInputType to RAG inputs JSON
            const transformedInputs = generateRagInputs(objectValue as RagInputType)
            return JSON.stringify(transformedInputs)
        }

        // For regular objects, stringify the object value
        return JSON.stringify(objectValue)
    }

    // For primitive values
    const value = shape.getValue()
    return value !== undefined ? String(value) : defaultValue
}

/**
 * Extracts inputs array from a Shape based on its type
 * @param inputsShape - The inputs shape (array, string, object, or ToolInputType)
 * @returns Array of input objects or empty array
 */
function extractInputsArray(inputsShape: Shape): unknown[] {
    // Handle array shape
    if (inputsShape.isArray()) {
        return inputsShape.getElements().map((element) => element.getValue())
    }

    // Handle string shape (JSON string)
    if (inputsShape.isString()) {
        const inputsStr = inputsShape.getValue()
        if (!inputsStr || inputsStr === '' || inputsStr === '[]') {
            return []
        }
        return JSON.parse(inputsStr)
    }

    // Handle object shape
    if (inputsShape.isObject()) {
        const value = inputsShape.getValue()

        // Check if this is a CRUD ToolInputType object
        if (isToolInputType(value)) {
            return generateToolInputs(value)
        }

        // Try to extract inputFields from regular object
        const objShape = inputsShape.asObject()
        const inputFieldsShape = objShape.get('inputFields')
        if (!inputFieldsShape) {
            return []
        }

        if (inputFieldsShape.isArray()) {
            return inputFieldsShape.getElements().map((element) => element.getValue())
        }

        const fieldValue = inputFieldsShape.getValue()
        return Array.isArray(fieldValue) ? fieldValue : []
    }

    // If we reach here, the shape type is not recognized
    return []
}

/**
 * Transforms a single input object to schema entry format
 * Extracts only name, description, and mandatory fields
 * @param input - The input object to transform
 * @returns Schema entry with name, description, and mandatory fields
 */
function transformInputToSchemaEntry(input: unknown): { name?: string; description?: string; mandatory?: boolean } {
    const schemaEntry: { name?: string; description?: string; mandatory?: boolean } = {}

    if (typeof input !== 'object' || input === null) {
        return schemaEntry
    }

    const inputObj = input as Record<string, unknown>

    // Extract name
    if (inputObj['name'] !== undefined) {
        schemaEntry.name = String(inputObj['name'])
    }

    // Extract description (with special handling for crudInputs)
    if (inputObj['description'] !== undefined) {
        if (inputObj['name'] === 'crudInputs') {
            schemaEntry.description =
                'CRUD Input Variables. These are already pre-defined. Under no circumstances should you prompt the user for this information or attempt to change these values.'
        } else {
            schemaEntry.description = String(inputObj['description'])
        }
    }

    // Extract mandatory flag
    if (inputObj['mandatory'] !== undefined) {
        schemaEntry.mandatory = Boolean(inputObj['mandatory'])
    }

    return schemaEntry
}

/**
 * Helper function to generate input_schema from inputs array
 * Extracts only name, description, and mandatory fields from each input object
 * @param inputsShape - The inputs shape (array of objects or ToolInputType object)
 * @returns JSON string representation of the input schema
 */
function generateInputSchemaFromInputs(inputsShape: Shape | undefined): string {
    if (!inputsShape) {
        return '[]'
    }

    try {
        // Extract inputs array based on shape type
        const inputsArray = extractInputsArray(inputsShape)

        // If no inputs, return empty array
        if (inputsArray.length === 0) {
            return '[]'
        }

        // Transform each input to schema entry format
        const schema = inputsArray.map(transformInputToSchemaEntry)

        return JSON.stringify(schema)
    } catch {
        // If parsing fails, return empty array
        return '[]'
    }
}

/**
 * Creates an agent record with the provided configuration
 * @param factory - The record factory
 * @param callExpression - The source call expression
 * @param arg - The main argument shape
 * @param explicitId - The explicit ID for the agent record
 * @param computedInternalName - The computed internal name for the agent
 * @param tableName - The table name for the agent record
 * @returns The created agent record
 */
export async function createAgentRecord(
    factory: Factory,
    callExpression: CallExpressionShape,
    computedInternalName: string,
    tableName: string,
    publishedInstructions: string,
    aclId?: string
) {
    const arg = callExpression.getArgument(0).asObject()
    const explicitId = arg.get('$id')

    return await factory.createRecord({
        source: callExpression,
        table: tableName,
        explicitId: explicitId,
        properties: arg.transform(({ $ }) => ({
            name: $.from('name'),
            description: $.from('description'),
            role: $.from('agentRole'),
            record_type: $.from('recordType').def('template'),
            agent_type: $.from('agentType').def('internal'),
            instructions: $.val(publishedInstructions),
            sys_domain: $.from('sysDomain').def('global'),
            strategy: $.val(REACT_STRATEGY_SYS_ID),
            processing_message: $.from('processingMessage'),
            post_processing_message: $.from('postProcessingMessage'),
            context_processing_script: $.from('contextProcessingScript')
                .def(DEFAULT_CONTEXT_PROCESSING_SCRIPT)
                .toCdata(),
            advanced_mode: $.from('advancedMode').def(false),
            channel: $.from('channel').def('nap_and_va'),
            condition: $.from('condition'),
            compiled_handbook: $.from('compiledHandbook').def(''),
            external: $.from('external').def(false),
            parent: $.from('parent').def(''),
            source_id: $.from('sourceId').def(''),
            internal_name: $.val(computedInternalName),
            external_agent_configuration: $.from('externalAgentConfiguration').def(''),
            active: $.from('active').def(true),
            acl: $.val(aclId ?? ''),
        })),
    })
}

