/**
 * Extracts published instructions from versionDetails array
 * @param arg - The argument shape containing versionDetails
 * @returns Object containing published instructions and count of published versions
 */
export function extractPublishedInstructions(arg: ObjectShape): { instructions: string; publishedCount: number } {
    const versionDetailsArray = arg.get('versionDetails')?.ifArray()
    if (!versionDetailsArray) {
        return { instructions: '', publishedCount: 0 }
    }

    let publishedInstructions = ''
    let publishedCount = 0
    const versionElements = versionDetailsArray.getElements()

    for (const versionElement of versionElements) {
        const versionObj = versionElement.asObject()
        const state = versionObj.get('state')?.ifString()?.getValue()
        if (state === 'published') {
            publishedCount++
            // Store the last published version's instructions
            publishedInstructions = versionObj.get('instructions')?.ifString()?.getValue() || ''
        }
    }

    return { instructions: publishedInstructions, publishedCount }
}

/**
 * Creates agent version records from versionDetails array
 * @param factory - The record factory
 * @param callExpression - The source call expression
 * @param agentRecordId - The ID of the parent agent record
 * @param tableName - The table name for the version record
 * @param agentTableName - The agent table name
 * @returns Array of created agent version records
 */
export async function createAgentVersionRecords(
    factory: Factory,
    callExpression: CallExpressionShape,
    agentRecordId: RecordId,
    tableName: string,
    agentTableName: string
) {
    const arg = callExpression.getArgument(0).asObject()
    const versionDetailsArray = arg.get('versionDetails')?.ifArray()

    // If versionDetails is provided as an array, create multiple version records
    if (versionDetailsArray) {
        const versionElements = versionDetailsArray.getElements()
        return await Promise.all(
            versionElements.map(async (versionElement) => {
                const versionDetails = versionElement.asObject()

                return await factory.createRecord({
                    source: callExpression,
                    table: tableName,
                    properties: versionDetails.transform(({ $ }) => ({
                        state: $.from('state').def('published'),
                        instructions: $.from('instructions'),
                        version_name: $.from('name').def('V1'),
                        condition: $.from('condition'),
                        target_id: $.val(agentRecordId),
                        sys_domain: $.def('global'),
                        version_number: $.from('number').def(1),
                        target_table: $.def(agentTableName),
                    })),
                })
            })
        )
    }

    // Fallback: create a single default version record if no versionDetails provided
    const defaultVersionRecord = await factory.createRecord({
        source: callExpression,
        table: tableName,
        properties: arg.transform(({ $ }) => ({
            state: $.def('draft'),
            instructions: $.def(''),
            version_name: $.from('name').def('V1'),
            target_id: $.val(agentRecordId),
            sys_domain: $.def('global'),
            version_number: $.def(1),
            target_table: $.def(agentTableName),
        })),
    })

    return [defaultVersionRecord]
}

/**
 * Resolve a single role value to sys_id
 * IMPORTANT: Only sys_ids (GUIDs) are supported for roleList
 * Role names are NOT supported - must use sys_ids
 * The role_list field is a List type, not a reference field, so role names won't resolve
 */
function resolveRoleToSysId(roleValue: Shape, diagnostics: Diagnostics): string | undefined {
    // If it's a Record, extract the sys_id
    const recordRef = roleValue.ifRecord()
    if (recordRef) {
        return recordRef.getId().getValue()
    }

    // Get string value
    const roleStr = roleValue.asString()?.getValue()
    if (!roleStr) {
        return undefined
    }

    // Check if it's a sys_id (GUID)
    if (isGUID(roleStr)) {
        return roleStr
    }

    // Role names are NOT supported - must use sys_ids
    diagnostics.error(
        roleValue,
        `roleList must contain only role sys_ids (GUIDs), not role names. ` +
            `Got: '${roleStr}'. Use the role sys_id when using roleList ` +
            `(e.g., '2831a114c611228501d4ea6c309d626d' for admin), or use roleMap for role names.`
    )
    return undefined
}

/**
 * Creates a data access configuration record and optional M2M role mapping records.
 * Supports `roleList` (sys_ids) and `roleMap` (role names). At least one must be non-empty unless `runAsUser` is set.
 */
export async function createDataAccessConfigRecord(
    factory: Factory,
    callExpression: CallExpressionShape,
    agentRecordId: RecordId,
    dataAccess: ObjectShape,
    tableName: string,
    agentTableName: string,
    diagnostics: Diagnostics,
    hasRunAsUser = false
) {
    const roleListArray = dataAccess.get('roleList')?.ifArray()
    const restrictionGUIDs: string[] = []

    if (roleListArray) {
        const roleElements = roleListArray.getElements()
        const resolvedSysIds = await Promise.all(
            roleElements.map((roleValue) => resolveRoleToSysId(roleValue, diagnostics))
        )
        for (const sysId of resolvedSysIds) {
            if (sysId) {
                restrictionGUIDs.push(sysId)
            }
        }
    }

    const roleListValue = restrictionGUIDs.join(',')

    const roleMapField = dataAccess.get('roleMap')
    const roleMapArray = roleMapField?.ifArray()
    const validatedRoleMapItems: Shape[] = []

    if (roleMapArray) {
        for (const role of roleMapArray.getElements()) {
            if (role.ifString()) {
                const roleValue = role.asString()!.getValue()
                if (isGUID(roleValue)) {
                    diagnostics.error(
                        roleMapField!,
                        `roleMap must contain role names, not sys_ids. ` +
                            `Got: '${roleValue}'. Use the role name (e.g., 'admin'), ` +
                            `or move the sys_id to dataAccess.roleList.`
                    )
                } else if (roleValue.trim() !== '') {
                    validatedRoleMapItems.push(role)
                }
            } else {
                validatedRoleMapItems.push(role)
            }
        }
    }

    if (!hasRunAsUser && restrictionGUIDs.length === 0 && validatedRoleMapItems.length === 0) {
        diagnostics.error(
            dataAccess,
            'dataAccess must have at least one of roleList or roleMap non-empty: ' +
                'provide sys_ids in roleList, role names in roleMap, or both.'
        )
    }

    const roleConfigRecord = await factory.createRecord({
        source: callExpression,
        table: tableName,
        properties: dataAccess.transform(({ $ }) => ({
            agent: $.val(agentRecordId.getValue()),
            agent_table: $.val(agentTableName),
            action: $.val('limit_to_roles'),
            role_list: $.val(roleListValue),
            description: $.from('description').def(''),
            name: $.val(agentRecordId.getValue()),
        })),
    })

    const records = [roleConfigRecord]

    for (const role of validatedRoleMapItems) {
        const roleReference = role.ifString()
            ? await factory.createReference({
                  source: role,
                  table: SYS_USER_ROLE,
                  keys: { name: role.asString()!.getValue() },
              })
            : role
        const mappingRecord = await factory.createRecord({
            source: role,
            table: SYS_AGENT_ACCESS_ROLE_MAPPING,
            properties: {
                agent_access_config: roleConfigRecord,
                role: roleReference,
            },
        })
        records.push(mappingRecord)
    }

    return records
}

