/**
 * Creates an agent tool M2M record (for linking to existing tools)
 * @param factory - The record factory
 * @param callExpression - The source call expression
 * @param agentRecordId - The ID of the parent agent record
 * @param toolConfig - The tool configuration shape combined from tool record and M2M
 * @param toolSysId - The sys_id of the existing tool to link to
 * @param tableName - The table name for the M2M record
 * @returns The created agent tool M2M record
 */
export async function createAgentToolM2MRecord(
    factory: Factory,
    callExpression: CallExpressionShape,
    agentRecordId: RecordId,
    toolConfig: ObjectShape,
    toolSysId: string,
    tableName: string
) {
    return await factory.createRecord({
        source: callExpression,
        table: tableName,
        properties: toolConfig.transform(({ $ }) => ({
            max_auto_executions: $.from('maxAutoExecutions').def(10),
            active: $.from('active').def(true),
            post_message: $.from('postMessage'),
            pre_message: $.from('preMessage'),
            sys_domain: $.def('global'),
            transformation_instructions: $.from('transformationInstructions'),
            execution_mode: $.from('executionMode').def('autopilot'),
            agent: $.val(agentRecordId),
            document_status: $.from('documentStatus'),
            tool: $.val(toolSysId),
            tool_attributes: $.from('toolAttributes').def('{}'),
            name: $.from('name'),
            output_transformation_strategy: $.from('outputTransformationStrategy'),
            inputs: $.from('inputs')
                .map((inputs) => {
                    // If this is the Web Search tool and inputs is empty, use default inputs
                    if (toolSysId === WEB_SEARCH_TOOL_SYS_ID) {
                        const inputsArray = inputs.ifArray()
                        if (!inputsArray || inputsArray.getElements().length === 0) {
                            return WEB_SEARCH_DEFAULT_INPUTS
                        }
                    }

                    // Get tool type from toolConfig
                    const toolType = toolConfig.get('type')?.ifString()?.getValue()
                    // Serialize the inputs with tool type context
                    return serializeToJson(inputs, toolType, '[]')
                })
                .def(toolSysId === WEB_SEARCH_TOOL_SYS_ID ? WEB_SEARCH_DEFAULT_INPUTS : '[]'),
            display_output: $.from('displayOutput').def(false),
            description: $.from('description'),
            timeout: $.from('timeout'),
            pre_run: $.from('preRun').def(false),
            post_processing_script: $.from('postProcessingScript').def(''),
            widgets: $.from('widgets').map((v) => {
                if (v.isArray()) {
                    return v
                        .getElements()
                        .map((w) => {
                            if (w.isRecord()) {
                                return w.getId().getValue()
                            }
                            return w.getValue()
                        })
                        .join(',')
                }
                return v.ifString()?.getValue() || ''
            }),
            // Use m2mSysOverrides for M2M record overrides, never fall back to sysOverrides
            // This ensures strict separation between tool record overrides and M2M record overrides
            sys_overrides: $.from('m2mSysOverrides').def(''),
        })),
    })
}

/**
 * Maps user-facing tool type to internal ServiceNow tool type
 * @param toolType - The user-facing tool type
 * @returns The internal ServiceNow tool type
 */
function mapToolTypeToInternal(toolType: string | undefined): string | undefined {
    if (toolType === 'search_retrieval') {
        return 'rag'
    }
    return toolType
}

/**
 * Creates an agent tool record
 * @param factory - The record factory
 * @param callExpression - The source call expression
 * @param toolDetails - The tool configuration shape combined from tool record and M2M
 * @param tableName - The table name for the tool record
 * @returns The created agent tool record
 */
export async function createAgentToolRecord(
    factory: Factory,
    callExpression: CallExpressionShape,
    toolDetails: ObjectShape,
    tableName: string
) {
    // Get the tool type to determine target_document_table
    const userToolType = toolDetails.get('type')?.ifString()?.getValue()
    // Map user-facing type to internal type (search_retrieval → rag)
    const toolType = mapToolTypeToInternal(userToolType)
    const targetDocumentTable = toolType ? TOOL_TYPE_TO_TARGET_TABLE_MAP[toolType] || '' : ''

    // Extract target_document based on tool type
    const targetDocument = extractTargetDocument(toolDetails, toolType)

    // Get inputs to generate input_schema
    const inputsShape = toolDetails.get('inputs')

    // Auto-generate CRUD script if not provided
    const autoGeneratedScript = generateCrudScript(inputsShape, toolType)

    return await factory.createRecord({
        source: callExpression,
        table: tableName,
        properties: toolDetails.transform(({ $ }) => ({
            name: $.from('name'),
            target_document: $.val(targetDocument),
            target_document_table: $.val(targetDocumentTable),
            script: autoGeneratedScript ? $.val(autoGeneratedScript).toCdata() : $.from('script').def('').toCdata(),
            post_processing_script: $.from('postProcessingScript').def(''),
            record_type: $.from('recordType').def('template'),
            description: $.from('description'),
            active: $.from('active').def(true),
            sys_domain: $.def('global'),
            sys_overrides: $.from('sysOverrides').def(''),
            type: $.val(toolType),
            input_schema: $.val(generateInputSchemaFromInputs(inputsShape)),
        })),
    })
}

