/**
 * Creates a data access configuration record and optional M2M role mapping records.
 * Supports `roleList` (sys_ids) and `roleMap` (role names). At least one must be non-empty unless `runAsUser` is set.
 */
export async function createDataAccessConfigRecord(
    factory: Factory,
    callExpression: CallExpressionShape,
    workflowRecordId: RecordId,
    dataAccess: ObjectShape,
    tableName: string,
    diagnostics: Diagnostics,
    hasRunAsUser = false
) {
    const roleListArray = dataAccess.get('roleList')?.ifArray()
    const restrictionGUIDs: string[] = []

    if (roleListArray) {
        const roleElements = roleListArray.getElements()
        for (const roleValue of roleElements) {
            const resolvedSysId = resolveRoleToSysId(roleValue, diagnostics)
            if (resolvedSysId) {
                restrictionGUIDs.push(resolvedSysId)
            }
        }
    }

    const roleListValue = restrictionGUIDs.join(',')

    const roleMapField = dataAccess.get('roleMap')
    const roleMapArray = roleMapField?.ifArray()
    const validatedRoleMapItems: Shape[] = []

    if (roleMapArray) {
        for (const role of roleMapArray.getElements()) {
            if (role.ifString()) {
                const roleValue = role.asString()!.getValue()
                if (isGUID(roleValue)) {
                    diagnostics.error(
                        roleMapField!,
                        `roleMap must contain role names, not sys_ids. ` +
                            `Got: '${roleValue}'. Use the role name (e.g., 'admin'), ` +
                            `or move the sys_id to dataAccess.roleList.`
                    )
                } else if (roleValue.trim() !== '') {
                    validatedRoleMapItems.push(role)
                }
            } else {
                validatedRoleMapItems.push(role)
            }
        }
    }

    if (!hasRunAsUser && restrictionGUIDs.length === 0 && validatedRoleMapItems.length === 0) {
        diagnostics.error(
            dataAccess,
            'dataAccess must have at least one of roleList or roleMap non-empty: ' +
                'provide sys_ids in roleList, role names in roleMap, or both.'
        )
    }

    const roleConfigRecord = await factory.createRecord({
        source: callExpression,
        table: tableName,
        properties: dataAccess.transform(({ $ }) => ({
            agent: $.val(workflowRecordId.getValue()),
            agent_table: $.val(SN_AIA_USECASE),
            action: $.val('limit_to_roles'),
            role_list: $.val(roleListValue),
            description: $.from('description').def(''),
            name: $.val(workflowRecordId.getValue()),
        })),
    })

    const records = [roleConfigRecord]

    for (const role of validatedRoleMapItems) {
        const roleReference = role.ifString()
            ? await factory.createReference({
                  source: role,
                  table: SYS_USER_ROLE,
                  keys: { name: role.asString()!.getValue() },
              })
            : role
        const mappingRecord = await factory.createRecord({
            source: role,
            table: SYS_AGENT_ACCESS_ROLE_MAPPING,
            properties: {
                agent_access_config: roleConfigRecord,
                role: roleReference,
            },
        })
        records.push(mappingRecord)
    }

    return records
}
